css:
.closing {
  position: relative;
  background: var(--bg-alt);
  border-top: 1px solid var(--border-alt);
}
/* As bordas do CTA duplicavam com a do bloco. */
.closing .cta-link {
  border-top: 0; border-bottom: 1px solid var(--border-alt);
  padding-top: 90px; padding-bottom: 90px;
}

.cta-link {
  display: block; position: relative; z-index: 2; padding: 70px 40px;
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
  text-decoration: none; color: inherit;
}
.cta-link:hover { color: inherit; }
.cta-inner { max-width: 1360px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 32px; }
.cta-text { font-family: 'Sora', sans-serif; font-weight: 800; font-size: clamp(28px, 4.5vw, 52px); letter-spacing: -0.03em; line-height: 1.1; color: #fff; max-width: 720px; }
.cta-button { flex-shrink: 0; }
.cta-arrow { transition: transform 0.25s; }
.cta-link:hover .cta-arrow { transform: translateX(6px); }

@media (max-width: 700px) {
  .cta-link { padding: 48px 20px; }
  .closing .cta-link { padding-top: 64px; padding-bottom: 64px; }
}

/* botão (ver componente Anti Metal Button) */
.amb-btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  padding: 16px 28px; color: var(--bg);
  font-family: 'JetBrains Mono', monospace; font-size: 12px; font-weight: 600;
  letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap;
  background: linear-gradient(135deg, var(--amb-from), var(--amb-to));
  border: 1px solid transparent; border-radius: 4px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.25);
}
